import collections,datetime,hashlib,itertools,json,os,pathlib,platform,resource,signal,subprocess,sys,tempfile,time
ROOT=pathlib.Path(os.environ.get('RULE30_REPLAY_ROOT','/home/ryan/rule30-lab'))
OUT=pathlib.Path(os.environ.get('RULE30_REPLAY_OUTPUT','/tmp/astra_once_zero_independent.json'))
START=time.monotonic();resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30));resource.setrlimit(resource.RLIMIT_CPU,(120,120));signal.alarm(120)
aff=sorted(os.sched_getaffinity(0));os.sched_setaffinity(0,{aff[0]})
def canon(x):return json.dumps(x,sort_keys=True,separators=(',',':')).encode()
def sha(x):return hashlib.sha256(x).hexdigest()
def T(x):
    bits=[(x>>i)&1 for i in range(x.bit_length()+2)]
    return sum((bits[i]^((bits[i-1] if i>=1 else 0)|(bits[i-2] if i>=2 else 0)))<<i for i in range(len(bits)))
def G(g,x):return T(x) if g=='t' else T(x)^1 if g=='u' else T(2*x+1)>>1
def A(x):return T(x)>>2
LETTERS='tup';S='tupp';M=1<<16
def omega(q,g):return int((q%16==0 and g=='t') or (q%16==1 and g=='u'))
def gate(x):return 'u' if x%16==7 else 't' if x%16==11 else None
def admissible(w):return not any(bad in w for bad in ['uu','ttttt','ututtu'])
def F(x):
    g=gate(x);assert g is not None
    return G(g,G('p',x>>2))
def wordstate(root,w):
    x=root;prefixes=[x];counts=[0]*48
    for g in w:
        counts[3*(x%16)+LETTERS.index(g)]+=1;x=G(g,x);prefixes.append(x)
    return {'word_after_root':w,'endpoint':x,'endpoint_hex':hex(x),'prefixes':prefixes,'counts48':counts,'W_star':counts[0]+counts[4]}
def H(root,w):
    st=wordstate(root,w);out=''.join(S[x%4] for x in st['prefixes'][1:])
    other=wordstate(root,out);assert other['prefixes']==[A(x) for x in st['prefixes']]
    return out
small=0;iterate_edges=0
for root in [3,1]:
    for n in range(6):
        for letters in itertools.product(LETTERS,repeat=n):
            w=''.join(letters);old=wordstate(root,w);cur=w;ap=old['prefixes']
            for age in range(1,4):
                cur=H(root,cur);prev=ap;ap=[A(x) for x in ap]
                predicted=sum(omega(ap[j],S[prev[j+1]%4]) for j in range(n))
                predicted_counts=[0]*48
                for j in range(n):predicted_counts[3*(ap[j]%16)+LETTERS.index(S[prev[j+1]%4])]+=1
                assert wordstate(root,cur)['counts48']==predicted_counts
                assert wordstate(root,cur)['W_star']==predicted
                iterate_edges+=n
            small+=1
pullback_forbidden=[(q,g) for q in range(64) for g in LETTERS if omega(A(q),S[G(g,q)%4])]
for q in range(64):
    if gate(q):assert omega(A(q),gate(q))==0
graph=[];rev=[[] for _ in range(M)];edges=[];targets=[];unfiltered_targets=[];target_branches={}
for q in range(M):
    row=[]
    for g in LETTERS:
        y=G(g,q)%M
        if omega(A(q),S[y%4])==0:
            row.append((g,y));rev[y].append(q);edges.append([q,g,y])
    graph.append(row)
    if gate(q) and F(q)%16384==903 and omega(A(q),gate(q))==0:
        unfiltered_targets.append(q)
        if admissible(gate(q)+'utututu'):
            targets.append(q);target_branches[str(q)]=gate(q)
    x=q;bs=''
    for _ in range(7):
        g=gate(x)
        if g is None:break
        bs+=g;x=F(x)
    assert (len(bs)==7 and bs[1:]=='ututut')==(q in unfiltered_targets)
    assert (len(bs)==7 and bs[1:]=='ututut' and admissible(bs+'u'))==(q in targets)
dist=[-1]*M;queue=collections.deque(targets)
for q in targets:dist[q]=0
while queue:
    y=queue.popleft()
    for q in rev[y]:
        if dist[q]<0:dist[q]=dist[y]+1;queue.append(q)
for q,row in enumerate(graph):
    if dist[q]<0:assert all(dist[y]<0 for _,y in row)
    else:
        assert q in targets or any(dist[y]==dist[q]-1 for _,y in row)
        assert all(dist[y]<0 or dist[q]<=1+dist[y] for _,y in row)
witnesses={};forced_formula_letters=0;forced_formula_costs=0
for phase,root in [('p',3),('u',1)]:
    if dist[root]<0:
        witnesses[phase]={'reachable':False};continue
    q=root;w=''
    while dist[q]>0:
        g,y=next((g,y) for g,y in graph[q] if dist[y]==dist[q]-1)
        w+=g;q=y
    origin=wordstate(root,w);states=[origin];branches='';current=w
    for age in range(1,8):
        x=states[-1]['endpoint'];g=gate(x);assert g is not None
        branches+=g;current=H(root,current)+g;st=wordstate(root,current);assert st['endpoint']==F(x);states.append(st)
        expected='';predcost=0;predcounts=[0]*48
        for j,z in enumerate(origin['prefixes'][1:]):
            before=origin['prefixes'][j]
            for _ in range(age-1):z=A(z)
            letter=S[z%4];expected+=letter
            for _ in range(age):before=A(before)
            predcost+=omega(before,letter);predcounts[3*(before%16)+LETTERS.index(letter)]+=1
        suffixcost=0
        for birth in range(1,age+1):
            if birth==age:letter=branches[birth-1]
            else:
                z=states[birth]['endpoint']
                for _ in range(age-birth-1):z=A(z)
                letter=S[z%4]
            expected+=letter
            preceding=states[birth-1]['endpoint']
            for _ in range(age-birth+1):preceding=A(preceding)
            predcounts[3*(preceding%16)+LETTERS.index(letter)]+=1
        assert expected==current and predcounts==st['counts48']
        prefixes=st['prefixes'];n=len(w)
        suffixcost=sum(omega(prefixes[j],current[j]) for j in range(n,len(current)))
        assert predcost+suffixcost==st['W_star'];forced_formula_letters+=len(current);forced_formula_costs+=1
    assert branches[1:]=='ututut' and admissible(branches+'u') and states[1]['W_star']==0
    witnesses[phase]={'reachable':True,'original_k':len(w)+1,'original_word_from_zero':phase+w,'target_residue':q,'branches':branches,'states':states,'block_W_star':[states[1]['W_star'],states[7]['W_star']]}
gate_chains={}
for q in unfiltered_targets:
    values=[q];bs=''
    for _ in range(7):
        bs+=gate(values[-1]);values.append(F(values[-1]))
    gate_chains[str(q)]={'states':values,'branches':bs,'first_output_mod16384':values[1]%16384,'admissibility_word':bs+'u','admissible':admissible(bs+'u')}
summary={'raw_target_gate_chains':gate_chains,'completed':True,'failures':[],'modulus':M,'targets':targets,'unfiltered_targets':unfiltered_targets,'rejected_target':{'residue':9879,'observed_branches':'uututut','admissibility_word':'uutututu','forbidden_factor':'uu'},'target_branches':target_branches,'allowed_edges':len(edges),'edges_sha256':sha(canon(edges)),
 'pullback_forbidden_mod64':pullback_forbidden,'reverse_distances':dist,'reachable_vertices':sum(d>=0 for d in dist),'root_distances':{'p':dist[3],'u':dist[1]},
 'small_words_checked':small,'small_iterated_edge_checks':iterate_edges,'small_scanner_ages':[1,2,3],
 'all_residues_direct_seven_gate_equivalence_checked':M,'all_permitted_append_costs_mod64_zero':True,
 'forced_formula_letters_checked':forced_formula_letters,'forced_formula_costs_checked':forced_formula_costs,'forced_formula_full48_tables_checked':forced_formula_costs,'witnesses':witnesses}
